using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using Suborned.Sim;
using Xunit;

public class GoalDebriefCaseWatchExportTests
{
    static string Write(Debrief d)
    {
        var w = new JWriter();
        d.Write(w);
        return w.ToString();
    }

    static JsonElement Parse(string text)
    {
        using var doc = JsonDocument.Parse(text);
        return doc.RootElement.Clone();
    }

    static JsonElement Property(JsonElement value, string name)
    {
        Assert.Equal(JsonValueKind.Object, value.ValueKind);
        Assert.True(value.TryGetProperty(name, out var result));
        return result;
    }

    static void SameJson(JsonElement expected, JsonElement actual)
    {
        Assert.Equal(expected.ValueKind, actual.ValueKind);
        if (expected.ValueKind == JsonValueKind.Object)
        {
            var a = expected.EnumerateObject().OrderBy(p => p.Name, StringComparer.Ordinal).ToArray();
            var b = actual.EnumerateObject().OrderBy(p => p.Name, StringComparer.Ordinal).ToArray();
            Assert.Equal(a.Select(p => p.Name).ToArray(), b.Select(p => p.Name).ToArray());
            for (int i = 0; i < a.Length; i++) SameJson(a[i].Value, b[i].Value);
        }
        else if (expected.ValueKind == JsonValueKind.Array)
        {
            var a = expected.EnumerateArray().ToArray();
            var b = actual.EnumerateArray().ToArray();
            Assert.Equal(a.Length, b.Length);
            for (int i = 0; i < a.Length; i++) SameJson(a[i], b[i]);
        }
        else if (expected.ValueKind == JsonValueKind.String)
            Assert.Equal(expected.GetString(), actual.GetString());
        else
            Assert.Equal(expected.GetRawText(), actual.GetRawText());
    }

    static void Collections(Debrief expected, JsonElement json)
    {
        var next = Property(json, "nextMission");
        var cases = Property(next, "cases");
        var watch = Property(next, "areaWatch");
        Assert.Equal(JsonValueKind.Array, cases.ValueKind);
        Assert.Equal(JsonValueKind.Array, watch.ValueKind);
        var expectedCases = expected.Next.Cases.Select(c => new { who = c.who, kind = c.kind, place = c.place, missions = c.missions }).ToArray();
        var expectedWatch = expected.Next.AreaWatch.Select(a => new { place = a.place, guards = a.guards, cameras = a.cameras, missions = a.missions }).ToArray();
        SameJson(Parse(JsonSerializer.Serialize(expectedCases)), cases);
        SameJson(Parse(JsonSerializer.Serialize(expectedWatch)), watch);
    }

    // Independent projection of the pre-existing public JSON contract. The two new
    // collections are removed only at their designated nextMission location.
    static void LegacyFields(Debrief d, JsonElement actual)
    {
        var inv = new Dictionary<string, object>
        {
            ["count"] = d.Inv.Investigators,
            ["hops"] = d.Inv.Hops,
            ["sightings"] = d.Sightings,
            ["findings"] = d.Inv.Findings.Select(f =>
            {
                var row = new Dictionary<string, object>
                {
                    ["hop"] = f.Hop, ["who"] = f.Who,
                    ["outcome"] = f.Outcome, ["lead"] = f.Lead,
                    ["gives"] = f.Facts.ToArray()
                };
                if (f.Cause.Length > 0) row["because"] = f.Cause;
                return row;
            }).ToArray()
        };
        if (d.Inv.Hunted.Count > 0) inv["hunted"] = d.Inv.Hunted.ToArray();
        var next = new Dictionary<string, object>
        {
            ["ambush"] = d.Next.Ambush,
            ["ambushBy"] = d.Next.AmbushBy.ToArray(),
            ["standing"] = d.Next.Standing.Select(l => new
            {
                district = l.District, from = l.From, to = l.To, band = l.Band,
                cause = l.Cause, who = l.Who, mission = l.End - l.From,
                found = l.Found, word = l.Word, wordUncapped = l.WordUncapped,
                drift = l.Drift,
                moves = l.Moves.Select(m => new { delta = m.delta, cause = m.cause, who = m.who }).ToArray()
            }).ToArray(),
            ["lines"] = d.Next.Lines.Select(l => new { line = l.Line, who = l.Who, detail = l.Detail }).ToArray(),
            ["contacts"] = d.Next.Contacts.Select(c => new
            {
                who = c.Role.Length > 0 ? c.Role : c.Id, name = c.Name,
                need = c.Need, needKnown = c.KNeed,
                bravery = c.Sc[0], resentment = c.Sc[1], fear = c.Sc[2], loyalty = c.Sc[3]
            }).ToArray()
        };
        if (d.Next.Cases.Count > 0 || d.Next.CampaignTrail != 0)
        {
            next["campaignTrail"] = d.Next.CampaignTrail;
            next["campaignStanding"] = d.Next.CampaignStanding;
            next["openCases"] = d.Next.OpenCases;
            next["nextLevel"] = d.Next.NextLevel;
        }
        if (d.Next.Captives.Count > 0 || d.Next.CarSeenBy.Length > 0)
        {
            if (d.Next.CarSeenBy.Length > 0) next["carSeenBy"] = d.Next.CarSeenBy;
            next["captives"] = d.Next.Captives.Select(c => new
            {
                who = c.Op, why = c.Why, heldAt = c.HeldAt, holds = c.Holds,
                talksAt = c.TalksAt, rescueUntil = c.RescueUntil,
                bravery = c.Sc[0], resentment = c.Sc[1], fear = c.Sc[2], loyalty = c.Sc[3],
                left = c.Left, right = c.Right, gives = c.Facts.ToArray()
            }).ToArray();
        }
        var expected = new Dictionary<string, object>
        {
            ["publicSecurity"] = d.PublicSecurity,
            ["investigation"] = new { state = d.InvestigationState, cause = d.InvestigationCause },
            ["contacts"] = d.Contacts, ["loud"] = d.Loud,
            ["assets"] = d.Assets.ToArray(), ["route"] = d.Route.ToArray(),
            ["extraInterventions"] = d.Extra.ToArray(), ["chain"] = d.Chain.ToArray(),
            ["investigators"] = inv, ["nextMission"] = next,
            ["cell"] = d.Cell.Select(c => new { op = c.op, health = c.health, max = c.max }).ToArray(),
            ["captured"] = d.Captured.ToArray()
        };
        if (d.FightBranch.Length > 0)
            expected["finalFight"] = new
            {
                branch = d.FightBranch, hostiles = d.FightHostiles,
                downedByEnforcer = d.FightDownedByEnforcer, downedByGuard = d.FightDownedByGuard,
                downedByCell = d.FightDownedByCell, hitsTaken = d.FightHits,
                shots = d.FightShots, why = d.FightWhy.ToArray()
            };
        if (d.LeftBehind.Count > 0)
            expected["leftBehind"] = d.LeftBehind.Select(l => new { who = l.op, fate = l.fate, why = l.why }).ToArray();
        if (d.Cause != null) expected["cause"] = Parse(d.Cause.Json());

        var retained = new Dictionary<string, object>();
        foreach (var p in actual.EnumerateObject())
        {
            if (p.Name != "nextMission") retained.Add(p.Name, p.Value.Clone());
            else
            {
                var oldNext = new Dictionary<string, JsonElement>();
                foreach (var n in p.Value.EnumerateObject())
                    if (n.Name != "cases" && n.Name != "areaWatch") oldNext.Add(n.Name, n.Value.Clone());
                retained.Add(p.Name, oldNext);
            }
        }
        SameJson(Parse(JsonSerializer.Serialize(expected)), Parse(JsonSerializer.Serialize(retained)));
    }

    [Fact]
    public void SuccessfulHeadlessReportIncludesEmptyCollections()
    {
        var run = Scenarios.Run(Repo.Inputs, Scenarios.Find("S10")!);
        Assert.Equal(Outcome.Success, run.G.Result);
        var d = Debrief.Of(run.G);
        Assert.Empty(d.Next.Cases);
        Assert.Empty(d.Next.AreaWatch);
        var report = Parse(Report.Json("S10", run.G, run.Checks, true));
        var exported = Property(report, "debrief");
        Collections(d, exported);
        LegacyFields(d, exported);
        SameJson(Parse(Write(d)), exported);
    }

    [Fact]
    public void ScenarioConsequencesAreExportedWithoutChangingLegacyFields()
    {
        bool sawMissing = false, sawFound = false, sawSuccess = false;
        foreach (var scenario in Scenarios.All)
        {
            var run = Scenarios.Run(Repo.Inputs, scenario);
            var g = run.G;
            var next = g.BetweenMissions(g.Investigate());
            var before = Hash.State(g);
            var d = Debrief.Of(g);
            Assert.Equal(next.Cases.ToArray(), d.Next.Cases.ToArray());
            Assert.Equal(next.AreaWatch.ToArray(), d.Next.AreaWatch.ToArray());
            Assert.Equal((next.CampaignTrail, next.CampaignStanding, next.OpenCases, next.NextLevel),
                (d.Next.CampaignTrail, d.Next.CampaignStanding, d.Next.OpenCases, d.Next.NextLevel));
            Assert.Equal(before, Hash.State(g));
            var json = Parse(Write(d));
            LegacyFields(d, json);
            Collections(d, json);
            sawMissing |= next.Cases.Any(c => c.kind == "missing");
            sawFound |= next.Cases.Any(c => c.kind == "found-killing");
            if (g.Result == Outcome.Success)
            {
                sawSuccess = true;
                var report = Parse(Report.Json(scenario.Id, g, run.Checks, true));
                SameJson(json, Property(report, "debrief"));
                Assert.Equal(g.Tick, Property(report, "tick").GetInt32());
                Assert.Equal(g.Cash, Property(report, "cash").GetInt64());
                Assert.Equal(g.Trail, Property(report, "trail").GetInt32());
                Assert.Equal(g.Alert, Property(report, "alert").GetInt32());
                Assert.Equal(g.Standing, Property(report, "standing").GetInt32());
                Assert.Equal(Hash.Hex(g.StartHash), Property(report, "startHash").GetString());
                Assert.Equal(Hash.Hex(g.Checkpoints[g.Checkpoints.Count - 1].hash), Property(report, "finalHash").GetString());
            }
            Assert.Equal(before, Hash.State(g));
        }
        Assert.True(sawMissing);
        Assert.True(sawFound);
        Assert.True(sawSuccess);
    }

    [Fact]
    public void SerializerPreservesMultipleEntriesAssociationsOrderAndMultiplicity()
    {
        // Assemble a serialization boundary fixture solely from actual scenario
        // consequences. Repeated entries must remain repeated, not be coalesced.
        var d = Debrief.Of(Scenarios.Run(Repo.Inputs, Scenarios.Find("N47")!).G);
        Assert.NotEmpty(d.Next.Cases);
        Assert.NotEmpty(d.Next.AreaWatch);
        Assert.Contains(d.Next.Cases, c => c.kind == "missing");
        var originalCases = d.Next.Cases.ToArray();
        var originalWatch = d.Next.AreaWatch.ToArray();
        bool addedFound = false;
        foreach (var scenario in Scenarios.All)
        {
            var found = Debrief.Of(Scenarios.Run(Repo.Inputs, scenario).G).Next;
            if (!found.Cases.Any(c => c.kind == "found-killing")) continue;
            d.Next.Cases.AddRange(found.Cases);
            d.Next.AreaWatch.AddRange(found.AreaWatch);
            addedFound = true;
            break;
        }
        Assert.True(addedFound);
        d.Next.Cases.AddRange(originalCases);
        d.Next.AreaWatch.AddRange(originalWatch);
        var cases = d.Next.Cases.ToArray();
        var watch = d.Next.AreaWatch.ToArray();
        var aggregates = (d.Next.CampaignTrail, d.Next.CampaignStanding, d.Next.OpenCases, d.Next.NextLevel);
        var first = Write(d);
        Collections(d, Parse(first));
        LegacyFields(d, Parse(first));
        Assert.Equal(first, Write(d));
        Assert.Equal(cases, d.Next.Cases.ToArray());
        Assert.Equal(watch, d.Next.AreaWatch.ToArray());
        Assert.Equal(aggregates, (d.Next.CampaignTrail, d.Next.CampaignStanding, d.Next.OpenCases, d.Next.NextLevel));
    }

    [Theory]
    [InlineData("S10")]
    [InlineData("N47")]
    public void RepeatedReadsDoNotCommitAdvanceOrAlterReplay(string id)
    {
        var run = Scenarios.Run(Repo.Inputs, Scenarios.Find(id)!);
        var g = run.G;
        var hash = Hash.State(g);
        var checkpoints = g.Checkpoints.ToArray();
        var start = g.Start.Canonical();
        var record = Script.Write(g, Repo.Inputs.Hash);
        var progress = (g.Tick, g.Result, g.FailCode, g.Cash, g.Trail, g.Alert, g.Standing);
        var d = Debrief.Of(g);
        var cases = d.Next.Cases.ToArray();
        var watch = d.Next.AreaWatch.ToArray();
        var aggregates = (d.Next.CampaignTrail, d.Next.CampaignStanding, d.Next.OpenCases, d.Next.NextLevel);
        var first = Write(d);
        var report = Report.Json(id, g, run.Checks, true);
        for (int i = 0; i < 4; i++)
        {
            Assert.Equal(first, Write(d));
            var fresh = Debrief.Of(g);
            Assert.Equal(first, Write(fresh));
            Assert.Equal(cases, fresh.Next.Cases.ToArray());
            Assert.Equal(watch, fresh.Next.AreaWatch.ToArray());
            Assert.Equal(aggregates, (fresh.Next.CampaignTrail, fresh.Next.CampaignStanding, fresh.Next.OpenCases, fresh.Next.NextLevel));
            Assert.Equal(cases, d.Next.Cases.ToArray());
            Assert.Equal(watch, d.Next.AreaWatch.ToArray());
            Assert.Equal(report, Report.Json(id, g, run.Checks, true));
            Assert.Equal(hash, Hash.State(g));
            Assert.Equal(checkpoints, g.Checkpoints.ToArray());
            Assert.Equal(start, g.Start.Canonical());
            Assert.Equal(record, Script.Write(g, Repo.Inputs.Hash));
            Assert.Equal(progress, (g.Tick, g.Result, g.FailCode, g.Cash, g.Trail, g.Alert, g.Standing));
        }
        var script = Script.Parse(record);
        var replay = Engine.Play(Repo.Inputs, script.Start, script.Orders, script.Until);
        Assert.Equal("", script.Verify(replay, Repo.Inputs.Hash));
        Assert.Equal(checkpoints, replay.Checkpoints.ToArray());
        Assert.Equal(g.StartHash, replay.StartHash);
        Assert.Equal(hash, Hash.State(replay));
        Assert.Equal(progress, (replay.Tick, replay.Result, replay.FailCode, replay.Cash, replay.Trail, replay.Alert, replay.Standing));
        var replayDebrief = Debrief.Of(replay);
        Assert.Equal(cases, replayDebrief.Next.Cases.ToArray());
        Assert.Equal(watch, replayDebrief.Next.AreaWatch.ToArray());
        Assert.Equal(first, Write(replayDebrief));
        Collections(d, Parse(first));
        Collections(replayDebrief, Parse(Write(replayDebrief)));
        Assert.Equal(report, Report.Json(id, replay, run.Checks, true));

        // A fresh mission still starts from its supplied start, not a result
        // implicitly persisted by any of the reads above.
        var freshStart = Engine.New(Repo.Inputs, Start.Parse(JNode.Parse(start)));
        var secondStart = Engine.New(Repo.Inputs, Start.Parse(JNode.Parse(start)));
        var initial = Hash.State(freshStart);
        Write(Debrief.Of(g));
        Assert.Equal(initial, Hash.State(freshStart));
        Assert.Equal(initial, Hash.State(secondStart));
        freshStart.RunTo(Game.T(1));
        Write(Debrief.Of(g));
        secondStart.RunTo(Game.T(1));
        Assert.Equal(Hash.State(freshStart), Hash.State(secondStart));
    }
